import{_ as a,o as s,c as e,ai as o}from"./chunks/framework.BBSijY9B.js";const g=JSON.parse('{"title":"数据与报表","description":"用 Grok Bot 清洗数据、做分析、生成定期报表，并让每个数字都能追溯来源。","frontmatter":{"related":["/templates/data-reporter","/basics/files-reports","/automation/routines"],"title":"数据与报表","description":"用 Grok Bot 清洗数据、做分析、生成定期报表，并让每个数字都能追溯来源。","section":"roles","order":4,"tags":["角色","数据分析","报表","Excel"],"sources":["https://cursor.com/docs/grok-bot/work","https://docs.x.ai/grok-bot/computer-and-apps"],"wordCount":328,"readingTime":1,"head":[["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:title","content":"数据与报表 | WANGXXXL"}],["meta",{"property":"og:description","content":"用 Grok Bot 清洗数据、做分析、生成定期报表，并让每个数字都能追溯来源。"}],["meta",{"property":"og:url","content":"https://wangxxxl.com/roles/data-reports"}],["meta",{"property":"og:image","content":"https://wangxxxl.com/og/roles-data-reports-a9f878740b.png"}],["meta",{"property":"og:image:alt","content":"数据与报表 · WANGXXXL · wangxxxl.com"}],["meta",{"name":"twitter:title","content":"数据与报表 | WANGXXXL"}],["meta",{"name":"twitter:description","content":"用 Grok Bot 清洗数据、做分析、生成定期报表，并让每个数字都能追溯来源。"}],["meta",{"name":"twitter:image","content":"https://wangxxxl.com/og/roles-data-reports-a9f878740b.png"}],["meta",{"name":"twitter:image:alt","content":"数据与报表 · WANGXXXL · wangxxxl.com"}],["link",{"rel":"canonical","href":"https://wangxxxl.com/roles/data-reports"}]]},"headers":[],"relativePath":"roles/data-reports.md","filePath":"roles/data-reports.md","lastUpdated":1792485206000}'),n={name:"roles/data-reports.md"};function p(i,t,l,r,c,d){return s(),e("div",null,[...t[0]||(t[0]=[o(`<h1 id="数据与报表" tabindex="-1">数据与报表 <a class="header-anchor" href="#数据与报表" aria-label="Permalink to &quot;数据与报表&quot;">​</a></h1><p>Bot 的云电脑上可以真正运行代码（比如 Python）来处理数据，所以它算出来的数字是&quot;算&quot;的，不是&quot;猜&quot;的。对于经常和表格打交道的人，这能省下大量重复劳动。</p><h2 id="典型工作" tabindex="-1">典型工作 <a class="header-anchor" href="#典型工作" aria-label="Permalink to &quot;典型工作&quot;">​</a></h2><ul><li>合并、清洗来自多个来源的表格。</li><li>按固定口径生成日报、周报、月报。</li><li>做简单的统计分析和图表。</li><li>核对两份数据是否一致，找出差异。</li><li>把分析结果写成管理层看得懂的结论。</li></ul><h2 id="示例提示词" tabindex="-1">示例提示词 <a class="header-anchor" href="#示例提示词" aria-label="Permalink to &quot;示例提示词&quot;">​</a></h2><p><strong>数据清洗</strong></p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>附件是三个渠道导出的订单表，字段名不统一。请合并成一张表：</span></span>
<span class="line"><span>统一字段为&quot;日期、渠道、订单号、金额、状态&quot;；去掉重复订单号；</span></span>
<span class="line"><span>金额统一为两位小数；把无法识别的记录单独放在一个 Sheet 里，并说明原因。</span></span></code></pre></div><p><strong>对账</strong></p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>对比&quot;系统导出.xlsx&quot;和&quot;财务台账.xlsx&quot;，以订单号为准，</span></span>
<span class="line"><span>列出：只在一边出现的记录、金额不一致的记录。输出差异表，不要修改原文件。</span></span></code></pre></div><p><strong>分析 + 结论</strong></p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>基于这份月度数据，回答三个问题：哪个渠道增长最快？哪类产品退货率异常？</span></span>
<span class="line"><span>有没有明显的周期性？每个结论附上计算方法和对应的图表。</span></span>
<span class="line"><span>不确定的地方直接说不确定。</span></span></code></pre></div><p><strong>做成演示文稿</strong></p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>把上面的分析做成 6 页以内的 PPT：一页结论、三页图表、一页风险、一页建议。风格简洁。</span></span></code></pre></div><h2 id="推荐例程" tabindex="-1">推荐例程 <a class="header-anchor" href="#推荐例程" aria-label="Permalink to &quot;推荐例程&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>每周一早上 9 点，从共享网盘的&quot;每周导出&quot;文件夹读取最新数据，</span></span>
<span class="line"><span>按&quot;周报口径&quot;技能生成周报 Excel，存到 /workspace/周报/ 并发到这个对话。</span></span>
<span class="line"><span>如果文件夹里没有本周的新文件，直接告诉我，不要用上周的数据。</span></span></code></pre></div><div class="tip custom-block"><p class="custom-block-title">把&quot;口径&quot;写成技能</p><p>同一个指标，不同人算法可能不一样。把你的统计口径（比如&quot;有效订单 = 已支付且未退款&quot;）写进技能，每次计算就不会走样。</p></div><div class="warning custom-block"><p class="custom-block-title">常见坑</p><ul><li><strong>不说明口径就要结果</strong>：先定义清楚指标，再让它算。</li><li><strong>只看结论不看过程</strong>：让它在报表里附&quot;处理说明&quot;，至少抽查一次计算。</li><li><strong>用旧数据凑数</strong>：在例程里明确写&quot;没有新数据就报告，不要用旧数据&quot;。</li><li><strong>敏感数据外流</strong>：含个人信息的数据处理完及时删除，不要上传到无关的外部服务。</li></ul></div>`,17)])])}const h=a(n,[["render",p]]);export{g as __pageData,h as default};
